import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Crate Graph & Design Principles","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md"}'),r={name:"architecture/overview.md"};function o(c,e,d,i,l,p){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="crate-graph-design-principles" tabindex="-1">Crate Graph &amp; Design Principles <a class="header-anchor" href="#crate-graph-design-principles" aria-label="Permalink to &quot;Crate Graph &amp; Design Principles&quot;">​</a></h1><p>The SMQL engine is organized as a Rust workspace with 12 crates. Each crate has a single responsibility, and dependencies flow in one direction: downstream crates never depend on upstream ones.</p><h2 id="crate-map" tabindex="-1">Crate Map <a class="header-anchor" href="#crate-map" aria-label="Permalink to &quot;Crate Map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>smql-ast            Pure types. No logic, no I/O.</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-parser         Hand-written recursive descent lexer + parser.</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-catalog        Machine registry backed by DashMap.</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-storage        Storage trait + MemoryStorage + RocksDB (feature-gated).</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-timer          TimerManager for timeout transitions.</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-hooks          HookExecutor + EventBus (tokio::broadcast).</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-engine-core    The brain: spawn, transition, query, eval, alter.</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>smql-query          Thin re-exports (query types live in smql-ast).</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  +-- smql-server   Axum HTTP/JSON API + WebSocket + Prometheus metrics.</span></span>
<span class="line"><span>  +-- smql-cli      Clap CLI + rustyline REPL.</span></span>
<span class="line"><span>  +-- smql-sdk      HTTP client, FindBuilder, Subscription, typed API.</span></span>
<span class="line"><span>  +-- smql-codegen  Code generation from machine definitions.</span></span></code></pre></div><h2 id="what-each-crate-does" tabindex="-1">What Each Crate Does <a class="header-anchor" href="#what-each-crate-does" aria-label="Permalink to &quot;What Each Crate Does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Purpose</th></tr></thead><tbody><tr><td><code>smql-ast</code></td><td>AST types: <code>Value</code>, <code>Expression</code>, <code>Machine</code>, <code>Command</code>, <code>Query</code>. Every other crate depends on this.</td></tr><tr><td><code>smql-parser</code></td><td>Hand-written recursive descent parser. Lexer uppercases keywords; <code>expect_ident()</code> preserves original case. Produces <code>Vec&lt;Statement&gt;</code>.</td></tr><tr><td><code>smql-catalog</code></td><td><code>MachineCatalog</code> backed by <code>DashMap&lt;String, Machine&gt;</code>. Concurrent read/write without a global lock.</td></tr><tr><td><code>smql-storage</code></td><td>The <code>Storage</code> trait plus two implementations: <code>MemoryStorage</code> (DashMap-based, always available) and <code>RocksDBStorage</code> (behind the <code>rocksdb</code> feature flag).</td></tr><tr><td><code>smql-timer</code></td><td><code>TimerManager</code> with a dual-index design (BTreeMap by deadline, HashMap by key) for efficient scheduling and O(1) cancellation.</td></tr><tr><td><code>smql-hooks</code></td><td><code>HookExecutor</code> runs lifecycle hooks. <code>EventBus</code> uses <code>tokio::broadcast</code> for EMIT. BEFORE hooks are sync and can reject; everything else is fire-and-forget.</td></tr><tr><td><code>smql-engine-core</code></td><td>The engine. Owns spawn, transition, query execution, expression evaluation, and ALTER MACHINE. Contains <code>eval_expr()</code> directly (not in smql-query) to avoid circular dependencies.</td></tr><tr><td><code>smql-query</code></td><td>Thin wrapper that re-exports query types from <code>smql-ast</code>. Exists for API clarity.</td></tr><tr><td><code>smql-server</code></td><td>Axum HTTP server. Routes, JSON handlers, WebSocket subscriptions, Prometheus metrics. Metrics live here, not in the engine.</td></tr><tr><td><code>smql-cli</code></td><td><code>clap</code> for argument parsing, <code>rustyline</code> for the interactive REPL. Connects to the server or runs embedded.</td></tr><tr><td><code>smql-sdk</code></td><td>Rust HTTP client for the SMQL server. <code>SmqlClient</code> constructs SMQL strings from builder parameters since the server only accepts <code>POST /execute</code> with <code>{&quot;smql&quot;: &quot;...&quot;}</code>.</td></tr><tr><td><code>smql-codegen</code></td><td>Generates Rust types from machine definitions. Maps SMQL types to Rust: <code>TEXT</code> to <code>String</code>, <code>INT</code> to <code>i64</code>, <code>MONEY</code> to <code>(i64, String)</code>, etc.</td></tr></tbody></table><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><h3 id="engine-stays-dependency-free-from-infrastructure" tabindex="-1">Engine stays dependency-free from infrastructure <a class="header-anchor" href="#engine-stays-dependency-free-from-infrastructure" aria-label="Permalink to &quot;Engine stays dependency-free from infrastructure&quot;">​</a></h3><p><code>smql-engine-core</code> has no knowledge of Axum, Prometheus, or any transport layer. Metrics are instrumented in the server handlers. Timeout metrics go through an EventBus subscriber in the server, not by coupling the engine to prometheus. This keeps the engine testable and reusable.</p><h3 id="hand-written-parser-for-control-and-diagnostics" tabindex="-1">Hand-written parser for control and diagnostics <a class="header-anchor" href="#hand-written-parser-for-control-and-diagnostics" aria-label="Permalink to &quot;Hand-written parser for control and diagnostics&quot;">​</a></h3><p>There is no parser combinator library. The lexer and parser are written by hand as a recursive descent parser. This gives full control over error messages, keyword handling, and syntax extensions. Keywords are uppercased during lexing so matching is case-insensitive, but identifiers preserve their original casing.</p><h3 id="dashmap-for-lock-free-concurrency" tabindex="-1">DashMap for lock-free concurrency <a class="header-anchor" href="#dashmap-for-lock-free-concurrency" aria-label="Permalink to &quot;DashMap for lock-free concurrency&quot;">​</a></h3><p>The catalog and memory storage both use <code>DashMap</code> from the <code>dashmap</code> crate. Each shard in a <code>DashMap</code> can be accessed independently, which means concurrent reads and writes to different keys never block each other. No global mutex, no RwLock around the whole map.</p><h3 id="arc-based-sharing-throughout" tabindex="-1">Arc-based sharing throughout <a class="header-anchor" href="#arc-based-sharing-throughout" aria-label="Permalink to &quot;Arc-based sharing throughout&quot;">​</a></h3><p>The <code>Engine</code> holds <code>Arc&lt;dyn Storage&gt;</code>, <code>Arc&lt;MachineCatalog&gt;</code>, and other shared resources. The server&#39;s <code>AppState</code> is <code>Clone</code> because every field is an <code>Arc</code>. This makes it trivial to pass state into Axum handlers and tokio tasks.</p><h3 id="feature-flags-for-optional-backends" tabindex="-1">Feature flags for optional backends <a class="header-anchor" href="#feature-flags-for-optional-backends" aria-label="Permalink to &quot;Feature flags for optional backends&quot;">​</a></h3><p>RocksDB is gated behind the <code>rocksdb</code> feature in <code>smql-storage</code>, <code>smql-server</code>, and <code>smql-cli</code>. A build without this feature compiles faster and has no native dependency on librocksdb. The <code>MemoryStorage</code> is always available.</p><h3 id="map-literals-and-spawn-in-the-ast" tabindex="-1">Map literals and SPAWN in the AST <a class="header-anchor" href="#map-literals-and-spawn-in-the-ast" aria-label="Permalink to &quot;Map literals and SPAWN in the AST&quot;">​</a></h3><p>Map literals <code>{key: value}</code> are represented as a <code>__map</code> FunctionCall node in the AST. Similarly, <code>SPAWN Machine {}</code> inside a MUTATE clause becomes a <code>__spawn</code> FunctionCall. The engine detects <code>__spawn</code> before calling <code>eval_expr()</code> because spawn is an async operation that cannot be handled inside the synchronous expression evaluator.</p><h2 id="dependency-flow" tabindex="-1">Dependency Flow <a class="header-anchor" href="#dependency-flow" aria-label="Permalink to &quot;Dependency Flow&quot;">​</a></h2><p>The critical rule: <strong>dependencies flow downward</strong>. <code>smql-ast</code> depends on nothing. <code>smql-parser</code> depends on <code>smql-ast</code>. <code>smql-engine-core</code> depends on most lower crates. <code>smql-server</code> and <code>smql-cli</code> depend on <code>smql-engine-core</code> but never the reverse.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>smql-server ─┐</span></span>
<span class="line"><span>smql-cli ────┤</span></span>
<span class="line"><span>smql-sdk ────┴──► smql-engine-core ──► smql-hooks</span></span>
<span class="line"><span>smql-codegen                       ──► smql-timer</span></span>
<span class="line"><span>                                   ──► smql-storage ──► smql-catalog ──► smql-ast</span></span>
<span class="line"><span>                                                                     ──► smql-parser</span></span></code></pre></div><p>This means you can use the engine as a library without pulling in Axum or clap. You can use the parser without pulling in the engine. You can use the AST types without pulling in anything.</p>`,23)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
